import{_ as r,a0 as o,w as p,s as m,ao as l,I as s,x as i,a1 as t,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"10 款你可以通过 Wine 在 Linux 上玩的游戏 | LCTT x X-CMD","titleTemplate":false,"description":"10 款你可以通过 Wine 在 Linux 上玩的游戏 | LCTT (201903) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"10 款你可以通过 Wine 在 Linux 上玩的游戏 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"10 款你可以通过 Wine 在 Linux 上玩的游戏 | LCTT (201903) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201903/20171005 10 Games You Can Play on Linux with Wine","title":"10 款你可以通过 Wine 在 Linux 上玩的游戏","tag":"201903","desc":""},"relativePath":"201903/20171005 10 Games You Can Play on Linux with Wine.md","filePath":"[post].md"}'),u={name:"201903/20171005 10 Games You Can Play on Linux with Wine.md"};function d(h,e,w,W,x,g){const a=o("Link");return p(),m("div",null,[e[19]||(e[19]=l('<h1 id="_10-款你可以通过-wine-在-linux-上玩的游戏" tabindex="-1">10 款你可以通过 Wine 在 Linux 上玩的游戏 <a class="header-anchor" href="#_10-款你可以通过-wine-在-linux-上玩的游戏" aria-label="Permalink to “10 款你可以通过 Wine 在 Linux 上玩的游戏”">​</a></h1><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/wine-games-feat.jpg" alt=""></p><p>Linux <em>确实</em> 能玩游戏，而且还能玩不少游戏。独立游戏在 Linux 平台上蓬勃发展，顶级的独立游戏也常常会在发售首日便发布 Linux 版本。然而，3A 游戏大作的开发者们却常常忽略 Linux，所以你不会很快就能玩上身边朋友们谈论正火的那些游戏。</p><p>但情况还没有糟透。Wine —— 一个能使 Windows 应用在类似 Linux、BSD 和 OS X 上运行的兼容层，在支持的游戏数量和性能表现上都取得了巨大进步。很多游戏大作都可以在 Wine 的支持下运行。你不能完全释放本机性能，但还是可以跑起来游戏，运行也还算流畅，当然这也要取决与你的系统配置。下面我们来盘点一下这些可能会令你大吃一惊的可以通过 Wine 在 Linux 上玩的游戏。（LCTT 译注：本文原文发表于 2017 年，有些信息可能有所过时。）</p><h3 id="_10、魔兽世界" tabindex="-1">10、魔兽世界 <a class="header-anchor" href="#_10、魔兽世界" aria-label="Permalink to “10、魔兽世界”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/wow.jpg" alt="World of Warcraft Wine" title="World of Warcraft Wine"></p><p>这款经典的 MMORPG 之王仍旧坚挺并保持活力。虽然这不是一款以画面见长的游戏，但想要开到全画质也需要费一些功夫。魔兽世界已经在 Wine 的支持下运行了很多年。到了最新资料片发布时，魔兽世界为它的 Mac 版本提供了 OpenGL 支持，使得游戏也可以很轻松地在 Linux 下运行。这已经不再是个问题了。</p>',7)),s("p",null,[e[1]||(e[1]=i("你需要通过 DX9 来运行游戏并从 ",-1)),t(a,{href:"https://www.maketecheasier.com/install-wine-gallium-nine-linux"},{default:n(()=>[...e[0]||(e[0]=[i("Gallium Nine",-1)])]),_:1}),e[2]||(e[2]=i(" 补丁来获得一些性能提升，不过你也可以放心大胆地在 Linux 中下副本了。",-1))]),e[20]||(e[20]=l('<h3 id="_9、上古卷轴-5-天际" tabindex="-1">9、上古卷轴 5：天际 <a class="header-anchor" href="#_9、上古卷轴-5-天际" aria-label="Permalink to “9、上古卷轴 5：天际”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/skyrim.jpg" alt="Skyrim Wine" title="Skyrim Wine"></p><p>上古卷轴 5 已经不是款新游戏了，但它的 mod 社区依旧活跃。如果你的 Linux 系统有足够资源的话，你可以很轻松地加上很多很多 mod。需要记住的是 Wine 运行时要比游戏占用更多的系统资源，所以使用 mod 时也要考虑这一点。</p><h3 id="_8、星际争霸-ii" tabindex="-1">8、星际争霸 II <a class="header-anchor" href="#_8、星际争霸-ii" aria-label="Permalink to “8、星际争霸 II”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/sc2.jpg" alt="StarCraft II Wine" title="StarCraft II Wine"></p><p>星际争霸 II 是成为市场上最受欢迎的 RTS 游戏之一，并且在 Wine 下运作良好。它实际上也是 Wine 下表现最好的游戏之一。</p><p>考虑到这款游戏本身的竞技性，你当然希望游戏能够流畅地运行。不过不用担心，只要你的硬件够用就绝对没问题。</p><p>这是一个你可以从 “staging” 补丁获益的例子，所以在你设置游戏时请继续使用它们。</p><h3 id="_7、辐射-3-辐射-新维加斯" tabindex="-1">7、辐射 3 / 辐射：新维加斯 <a class="header-anchor" href="#_7、辐射-3-辐射-新维加斯" aria-label="Permalink to “7、辐射 3 / 辐射：新维加斯”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/Fallout_3.jpg" alt="Fallout 3 Wine" title="Fallout 3 Wine"></p><p>在你提问之前，辐射 4 已经很快就准备就绪，也许就在你正读这篇文章的时候就可以玩了。就目前而言，辐射 3 和 辐射：新维加斯都能在有没有 mod 的情况下良好运行。这些游戏在 Wine 下运行地非常好，甚至还能加载大量 mod 来保持游戏的新鲜性和趣味性。在辐射 4 获得全面支持前玩这些旧作也不算是个很大的妥协。</p><h3 id="_6、doom-2016" tabindex="-1">6、Doom (2016) <a class="header-anchor" href="#_6、doom-2016" aria-label="Permalink to “6、Doom (2016)”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/doom.jpg" alt="Doom Wine" title="Doom Wine"></p><p>Doom（毁灭战士）是过去几年中最刺激的射击游戏之一。在 Wine 支持下并加载 “staging” 补丁可以流畅地运行最新版本。单人模式和多人模式都有很棒的游戏体验，而且也不需要花费大量时间来配置 Wine 和调整设置。所以你想在 Linux 上体验 3A 级射击游戏的话，不妨尝试一下 Doom 。</p><h3 id="_5、激战-2" tabindex="-1">5、激战 2 <a class="header-anchor" href="#_5、激战-2" aria-label="Permalink to “5、激战 2”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/gw2.jpg" alt="Guild Wars 2 Wine" title="Guild Wars 2 Wine"></p><p>激战 2 是一款无月卡（买断制）的融合了多人和迷宫探险元素的游戏。它在市场上很受欢迎，并自称在游戏中有着很多创新。你同样可以通过 Wine 在 Linux 上玩到这款游戏。</p><p>激战 2 也不算一款很老的 MMO 游戏。它试图以图像表现来保持现代风格，并具有着相当高分辨率的纹理和视觉效果。所有这些特点都能在 Wine 下顺利运行。</p><h3 id="_4、英雄联盟" tabindex="-1">4、英雄联盟 <a class="header-anchor" href="#_4、英雄联盟" aria-label="Permalink to “4、英雄联盟”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/League_of_legends.jpg" alt="League Of Legends Wine" title="League Of Legends Wine"></p><p>在 MOBA 游戏的世界中有两个强者：DoTA2 和英雄联盟。Valve 已经将 DoTA2 移植到 Linux 上很久了，但玩家们却从没在 Linux 上玩过英雄联盟。如果你是 Linux 的使用者并热衷英雄联盟，你还是可以通过 Wine 来玩这款你最爱的 MOBA 游戏。</p><p>英雄联盟是个很有趣的例子。它的游戏本身运行良好，但安装程序却会因为需要 Adobe Air 而中断。一些安装程序脚本例如 Lutris 和 PlayOnLinux 能帮你通过这一步骤。一旦安装完毕，你就可以毫无困难地运行游戏，甚至在激烈的战况中依旧畅快玩耍。</p><h3 id="_3、炉石传说" tabindex="-1">3、炉石传说 <a class="header-anchor" href="#_3、炉石传说" aria-label="Permalink to “3、炉石传说”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/HearthStone.jpg" alt="HearthStone Wine" title="HearthStone Wine"></p><p>炉石传说是一款流行且令人上瘾的免费卡牌游戏，你可在各种平台上来一局……除了 Linux。不过别担心，在 Wine 中你可以轻松玩到这款游戏。炉石并不大，所以即使在最低配置的系统里也都能玩，这是个好消息。不过由于它的竞技性所以还是要对游戏性能有一定要求。</p><p>玩炉石不需要任何特殊配置和补丁，直接开玩！</p><h3 id="_2、巫师-3" tabindex="-1">2、巫师 3 <a class="header-anchor" href="#_2、巫师-3" aria-label="Permalink to “2、巫师 3”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/witcher3.jpg" alt="Witcher 3 Wine" title="Witcher 3 Wine"></p><p>你不是唯一一个对在这份榜单中看到了巫师 3 而感到吃惊的人。在最新版 “stage” 补丁的支持下，你终于可以在 Linux 中体验这款游戏了。尽管最初承诺会有原生版本，但 Linux 玩家还是等了很久才迎来了巫师系列的第三部。</p><p>不过最好不要指望一切都能完美运行。巫师 3 <em>刚刚</em> 得到支持，有些内容可能还不会达到预期。也就是说，如果你只能用 Liux 来玩游戏，并且愿意处理一些问题。那么你也可以享受到这款完美游戏带来的初体验了。</p><h3 id="_1、守望先锋" tabindex="-1">1、守望先锋 <a class="header-anchor" href="#_1、守望先锋" aria-label="Permalink to “1、守望先锋”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/Overwatch.jpg" alt="Overwatch Wine" title="Overwatch Wine"></p><p>最后，让我们来谈谈 Linux 玩家心中的另一个“白鲸”。很多人认为守望先锋会像大多数暴雪游戏一样，在发售当日就能在 Wine 上获得支持。不过情况非常不同，因为守望先锋只支持 DX11，这也正是 Wine 面临的一个痛点。</p><p>守望先锋目前还不能拥有最佳性能表现，但是你还是可以通过装有特殊补丁的 Wine 和包括“staging”在内的一系列定制补丁包来运行游戏。这也说明了 Linux 玩家们真的很渴望游玩这款游戏，以至于自己开发了一套补丁来为它提供支持。</p><p>这份榜单当然会遗漏一些其他游戏。大多数是由于受欢迎程度或只能从 Wine 中得到有限的支持。其他暴雪游戏，如“风暴英雄”和“暗黑破坏神 3”也能很好地运行，但这样来写就会使暴雪游戏霸占这份榜单，这不是我们想突出的重点。</p>',35)),s("p",null,[e[4]||(e[4]=i("如果你正打算玩以上任一款游戏，请使用 Wine 的 ",-1)),t(a,{href:"https://www.maketecheasier.com/install-wine-gallium-nine-linux"},{default:n(()=>[...e[3]||(e[3]=[i("Gallium Nine",-1)])]),_:1}),e[5]||(e[5]=i(" 版本并装载“staging”补丁，否则游戏可能无法正常运行。“staging”中装载的最新补丁和提升要比正式的 Wine 发行版提供的内容要早很多，使用它会令你在性能上处于领先地位。",-1))]),e[21]||(e[21]=s("p",null,"说到进步，Wine 目前在对 DirectX11 的支持有了很大进步。对于 Windows 玩家这可能不算什么，但对于 Linux 玩家来说绝对算是一件大事。大多数游戏新作支持 DX11 和 DX12，而最新版本的 Wine 仍只是支持 DX9。有了 DX11 的支持，Wine 将会让很多过去无法在 Linux 上玩的游戏运行起来。所以，定期查看你最喜欢的 Windows 游戏是否也可以开始在 Wine 上运行，你可能会非常惊喜。",-1)),e[22]||(e[22]=s("hr",null,null,-1)),s("p",null,[e[7]||(e[7]=i("via: ",-1)),t(a,{href:"https://www.maketecheasier.com/games-play-on-linux-with-wine/"},{default:n(()=>[...e[6]||(e[6]=[i("https://www.maketecheasier.com/games-play-on-linux-with-wine/",-1)])]),_:1})]),s("p",null,[e[11]||(e[11]=i("作者：",-1)),t(a,{href:"https://www.maketecheasier.com/author/nickcongleton/"},{default:n(()=>[...e[8]||(e[8]=[i("Nick Congleton",-1)])]),_:1}),e[12]||(e[12]=i(" 译者：",-1)),t(a,{href:"https://github.com/Modrisco"},{default:n(()=>[...e[9]||(e[9]=[i("Modrisco",-1)])]),_:1}),e[13]||(e[13]=i(" 校对：",-1)),t(a,{href:"https://github.com/wxy"},{default:n(()=>[...e[10]||(e[10]=[i("wxy",-1)])]),_:1})]),s("p",null,[e[16]||(e[16]=i("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[14]||(e[14]=[i("LCTT",-1)])]),_:1}),e[17]||(e[17]=i(" 原创编译，",-1)),t(a,{href:"https://linux.cn/"},{default:n(()=>[...e[15]||(e[15]=[i("Linux中国",-1)])]),_:1}),e[18]||(e[18]=i(" 荣誉推出",-1))])])}const T=r(u,[["render",d]]);export{k as __pageData,T as default};
